public static boolean isBalanced(String str) {
    Stack<Character> s = new Stack<Character>();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '(' || ch == '[' || ch == '{') {
            s.push(ch);
        } else {
            if (s.isEmpty()) {
                return false;
            }
            char open = s.pop();
            if ((ch == ')' && open != '(') || (ch == ']' && open != '[') || (ch == '}' && open != '{')) {
                return false;
            }
        }
    }
    return s.isEmpty();
}

public static int maxDepth(String str) {
    Stack<Character> s = new Stack<Character>();
    int depth = 0;
    int max = 0;
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '(' || ch == '[' || ch == '{') {
            s.push(ch);
            depth++;
            if (depth > max) {
                max = depth;
            }
        } else {
            s.pop();
            depth--;
        }
    }
    return max;
}

